// Service worker, generated by build.mjs. Keeps an offline copy of the home
// page, our own games, the safer-play tools and every page the visitor has
// opened. It never touches requests to other origins, so consent-gated
// analytics and the Pragmatic Play demos are unaffected.
//
// Scripts and the stylesheet live under /assets/v<version>/ and fonts carry a
// content hash, so a file at one of those URLs never changes: the saved copy
// is served as it is. Everything else is checked with the server.
const CACHE = 'oql-v__VERSION__';
const PRECACHE = __PRECACHE__;

/** A URL whose content never changes. */
const fixed = (path) => /^\/assets\/(v[^/]+|fonts)\//.test(path);
/**
 * Fetch for the cache. A fixed URL may come from the browser's HTTP cache
 * (the page has usually just loaded it); anything else is revalidated with
 * the server, so a new worker never saves an old copy of a page.
 */
const fresh = (path) => new Request(path, { cache: fixed(path) ? 'default' : 'no-cache' });

/** This version's copy first, then the previous version's (a tab opened before a deploy still asks for old files). */
async function cached(request) {
  return (await (await caches.open(CACHE)).match(request)) || caches.match(request);
}

/** Save a page the visitor has open, with the scripts, styles and fonts it names. */
async function savePage(cache, href) {
  const url = new URL(href);
  if (url.origin !== self.location.origin) return;
  try {
    const response = await fetch(fresh(url.pathname));
    if (!response.ok || !(response.headers.get('content-type') || '').includes('text/html')) return;
    const html = await response.clone().text();
    await cache.put(url.pathname, response);
    const assets = [...html.matchAll(/(?:href|src)="(\/assets\/[^"#?]+)"/g)].map((m) => m[1]);
    for (const a of new Set(assets)) if (!(await cache.match(a))) await cache.add(fresh(a)).catch(() => {});
  } catch {}
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(PRECACHE.map(fresh)))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      // Keep the newest older cache for tabs still open from before this
      // deploy: their scripts' folder is gone from the server. Drop the rest.
      const older = (await caches.keys()).filter((k) => k.startsWith('oql-') && k !== CACHE);
      await Promise.all(older.slice(0, -1).map((k) => caches.delete(k)));
      await self.clients.claim();
      // The page a visitor lands on loads before this worker controls it, so
      // the fetch handler never sees it. Save the open pages now.
      const cache = await caches.open(CACHE);
      const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
      await Promise.all(windows.map((w) => savePage(cache, w.url)));
    })(),
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Pages: network first, so content is always current; the saved copy when offline.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request)
        .then((response) => {
          if (response.ok) {
            const copy = response.clone();
            event.waitUntil(caches.open(CACHE).then((cache) => cache.put(url.pathname, copy)));
          }
          return response;
        })
        .catch(async () => (await cached(url.pathname)) || (await cached('/offline/')) || Response.error()),
    );
    return;
  }

  // Everything else: the saved copy of this exact URL, query string included.
  event.respondWith(
    (async () => {
      const hit = await cached(request);
      if (hit && fixed(url.pathname)) return hit;
      const network = fetch(request).then((response) => {
        if (response.ok) {
          const copy = response.clone();
          event.waitUntil(caches.open(CACHE).then((cache) => cache.put(request, copy)));
        }
        return response;
      });
      if (!hit) return network;
      // A URL that can change (the manifest, an icon) is refreshed in the background for next time.
      event.waitUntil(network.catch(() => {}));
      return hit;
    })(),
  );
});
